-- Disposable database only: Vault shim checks authorization and transactions, not encryption.
begin;
create schema gmail_test;
create function gmail_test.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL Gmail: %',label;end if;raise notice 'ok - Gmail: %',label;end$$;
create function gmail_test.fails(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then raise notice 'ok - Gmail: % (refused)',label;return;end;raise exception 'FAIL Gmail: % was permitted',label;end$$;
grant usage on schema gmail_test to anon,authenticated,service_role;
grant execute on all functions in schema gmail_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('ce500000-0000-4000-8000-000000000001','gmail-a@example.com'),('ce500000-0000-4000-8000-000000000002','gmail-b@example.com');
insert into public.organizations(id,name,slug) values('ce500000-0000-4000-8000-000000000011','Gmail test','gmail-test');
insert into public.websites(id,organization_id,name) values('ce500000-0000-4000-8000-000000000021','ce500000-0000-4000-8000-000000000011','Gmail test');
insert into public.leads(id,organization_id,website_id,contact,message,source) values('ce500000-0000-4000-8000-000000000031','ce500000-0000-4000-8000-000000000011','ce500000-0000-4000-8000-000000000021','{"email":"visitor@example.com"}','Original inquiry','inquiries');
select set_config('request.jwt.claim.role','service_role',true);
set local role service_role;
select gmail_test.fails('select * from vigil.gmail_connections','service API has no direct credential table access');
select gmail_test.ok(public.gmail_connection('ce500000-0000-4000-8000-000000000001') is null,'unconnected user has no credential');
select public.save_gmail_connection('ce500000-0000-4000-8000-000000000001','mailbox-a@example.com','refresh-token-a-private');
select public.save_gmail_connection('ce500000-0000-4000-8000-000000000002','mailbox-b@example.com','refresh-token-b-private');
select gmail_test.ok(public.gmail_connection('ce500000-0000-4000-8000-000000000001')->>'email'='mailbox-a@example.com','connection is personal');
select gmail_test.ok(public.gmail_connection('ce500000-0000-4000-8000-000000000001')->>'refreshToken' is null,'status reads never decrypt credentials');
select gmail_test.ok(public.gmail_connection('ce500000-0000-4000-8000-000000000002',true)->>'refreshToken'='refresh-token-b-private','explicit service credential read selects only that account');
select gmail_test.ok(public.gmail_draft_lock('ce500000-0000-4000-8000-000000000001','ce500000-0000-4000-8000-000000000031','ce500000-0000-4000-8000-000000000041'),'first draft attempt gets lease');
select gmail_test.ok(not public.gmail_draft_lock('ce500000-0000-4000-8000-000000000001','ce500000-0000-4000-8000-000000000031','ce500000-0000-4000-8000-000000000042'),'parallel attempt is blocked');
select gmail_test.ok(not public.gmail_draft_lock('ce500000-0000-4000-8000-000000000001','ce500000-0000-4000-8000-000000000031','ce500000-0000-4000-8000-000000000042',true),'stale caller cannot release lease');
select gmail_test.ok(public.finish_gmail_draft('ce500000-0000-4000-8000-000000000001','ce500000-0000-4000-8000-000000000031','ce500000-0000-4000-8000-000000000041',(public.gmail_connection('ce500000-0000-4000-8000-000000000001')->>'connectedAt')::timestamptz,'r_example_draft','abc123'),'current lease persists provider identity');
select gmail_test.ok((select count(*)=1 from public.provider_links where resource_kind='gmail_draft_ce500000000040008000000000000001'),'draft identity exists only in provider links');
select public.remove_gmail_connection('ce500000-0000-4000-8000-000000000001');
select gmail_test.ok(public.gmail_connection('ce500000-0000-4000-8000-000000000001',true) is null,'disconnect removes credential');
select gmail_test.ok((select count(*)=0 from public.provider_links where resource_kind='gmail_draft_ce500000000040008000000000000001'),'disconnect clears old draft mapping');
select gmail_test.ok(not public.finish_gmail_draft('ce500000-0000-4000-8000-000000000001','ce500000-0000-4000-8000-000000000031','ce500000-0000-4000-8000-000000000041',now(),'r_stale','abc123'),'disconnected caller cannot persist a stale draft');
select gmail_test.ok(public.gmail_connection('ce500000-0000-4000-8000-000000000002',true)->>'refreshToken'='refresh-token-b-private','disconnect leaves other user unchanged');
reset role;
select gmail_test.ok((select count(*)=0 from vault.secrets where name='vigil.gmail.ce500000-0000-4000-8000-000000000001'),'Vault secret removed on disconnect');
delete from auth.users where id='ce500000-0000-4000-8000-000000000002';
select gmail_test.ok((select count(*)=0 from vault.secrets where name='vigil.gmail.ce500000-0000-4000-8000-000000000002'),'user deletion cleans its Vault credential');
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','ce500000-0000-4000-8000-000000000001',true);
set local role authenticated;
select gmail_test.fails('select * from vigil.gmail_connections','customer cannot read credential table');
select gmail_test.fails($q$select public.gmail_connection('ce500000-0000-4000-8000-000000000001',true)$q$,'customer cannot decrypt own credential through RPC');
select gmail_test.fails($q$select public.save_gmail_connection('ce500000-0000-4000-8000-000000000001','forged@example.com','forged-refresh-token')$q$,'customer cannot forge a connection');
select gmail_test.fails($q$select public.remove_gmail_connection('ce500000-0000-4000-8000-000000000002')$q$,'customer cannot disconnect another account');
reset role;
select set_config('request.jwt.claim.role','anon',true);
set local role anon;
select gmail_test.fails($q$select public.gmail_connection('ce500000-0000-4000-8000-000000000001')$q$,'anonymous caller cannot read a connection');
rollback;
